style.css:
@-moz-document domain("roblox.com") {
html, body, .container, #navigatiom {
    background: url("https://i.postimg.cc/6QnsDJWG/3.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #fff !important;
} 

.content, .container, .card, .section, .navbar, .header, #navigation, .game-card, .profile-header, .footer {
    background: transparent !important;
}

.content *, .container *, .card *, .section * {
    background: transparent !important;
}


a {
    color: #ff3b3b !important;
}


button, .btn-primary, .btn-common {
    background-color: #ff3b3b !important;
    color: #fff !important;
    border-radius: 6px !important;
    border: none !important;
}

button:hover, .btn-primary:hover, .btn-common:hover {
  background-color: #cc0000 !important;

  
}
}
